  return String(e?.message ?? e?.description ?? (typeof e === 'string' ? e : JSON.stringify(e ?? 'erreur inconnue'))).slice(0, 1000);
}
// >>>

// Fichier introuvable ou illisible, PDF illisible, OCR indisponible.
const item = $input.first().json;
const message = item.fileName === undefined && !item.error ? 'fichier introuvable dans /data/entrant' : messageErreur(item);
return [{ json: payloadEchec($('Réserver une facture').last().json, 'erreur_lecture', message, $execution.id, false) }];

